<?php $month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$first=strtotime($month.'-01');$monthStart=date('Y-m-01',$first);$nextMonth=date('Y-m-01',strtotime('+1 month',$first));$days=(int)date('t',$first);$offset=((int)date('N',$first))-1;$calHome=(int)($_GET['homestay_id']??($homestays[0]['homestay_id']??0));$booked=[];$blocked=[];if($pdo&&$calHome){$q=$pdo->prepare("SELECT check_in,check_out,status FROM bookings WHERE homestay_id=? AND status IN ('Pending','Confirmed','Checked-in') AND check_in < ? AND check_out > ?");$q->execute([$calHome,$nextMonth,$monthStart]);$booked=$q->fetchAll();$q=$pdo->prepare("SELECT start_date,end_date,reason FROM blocked_dates WHERE homestay_id=? AND status='Active' AND start_date < ? AND end_date >= ?");$q->execute([$calHome,$nextMonth,$monthStart]);$blocked=$q->fetchAll();}?>
<div class="screen-title"><div><span class="eyebrow">BOOKING & AVAILABILITY</span><h1>Availability calendar</h1><p>Active reservations and blocks are unavailable to customers.</p></div><a class="mock-button primary" href="?page=blocked-date-form">＋ Block dates</a></div><form class="toolbar-row" method="get"><input type="hidden" name="page" value="availability-calendar"><select name="homestay_id" onchange="this.form.submit()"><?php foreach($homestays as $h):?><option value="<?=(int)$h['homestay_id']?>" <?=$calHome===(int)$h['homestay_id']?'selected':''?>><?=esc($h['name'])?></option><?php endforeach;?></select><input type="month" name="month" value="<?=esc($month)?>"><button class="mock-button outline">View month</button><a class="mock-button outline" href="?page=availability-calendar&homestay_id=<?=$calHome?>&month=<?=date('Y-m',strtotime('-1 month',$first))?>">‹ Previous</a><a class="mock-button outline" href="?page=availability-calendar&homestay_id=<?=$calHome?>&month=<?=date('Y-m',strtotime('+1 month',$first))?>">Next ›</a></form><section class="mock-panel"><h2><?=esc(date('F Y',$first))?></h2><div class="calendar-grid"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $wd):?><div class="calendar-day head"><?=esc($wd)?></div><?php endforeach;?><?php for($i=0;$i<$offset;$i++):?><div class="calendar-day"></div><?php endfor;for($d=1;$d<=$days;$d++):$date=sprintf('%s-%02d',$month,$d);$isBooked=false;$isBlocked=false;$label='';foreach($booked as $b)if($date>=$b['check_in']&&$date<$b['check_out']){$isBooked=true;$label=$b['status'];}foreach($blocked as $b)if($date>=$b['start_date']&&$date<=$b['end_date']){$isBlocked=true;$label=$b['reason'];}?><div class="calendar-day <?=$isBlocked?'blocked-day':($isBooked?'booked':'')?>"><?=$d?><?php if($label):?><small><?=esc($label)?></small><?php endif;?></div><?php endfor;?></div><div class="calendar-legend"><span>Green · booked</span><span>Red · blocked</span><span>Blank · available</span></div></section>

