<?php $q=$pdo?$pdo->query("SELECT r.rating,r.comment,r.staff_reply,r.created_at,u.full_name,h.name homestay FROM reviews r JOIN bookings b ON b.booking_id=r.booking_id JOIN users u ON u.user_id=b.user_id JOIN homestays h ON h.homestay_id=b.homestay_id WHERE r.status='Visible' ORDER BY r.created_at DESC"):null;$publicReviews=$q?$q->fetchAll():[];$avg=$pdo?$pdo->query("SELECT COALESCE(AVG(rating),0) FROM reviews WHERE status='Visible'")->fetchColumn():0;?><div class="screen-title"><div><span class="eyebrow">GUEST STORIES</span><h1>Homestay reviews</h1></div></div><div class="review-rating-summary"><b><?=number_format((float)$avg,1)?></b><span>★★★★★</span><small><?=count($publicReviews)?> verified reviews</small></div><section class="mock-panel"><?php foreach($publicReviews as $r):?><article class="review-item"><div class="review-stars"><?=str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating'])?></div><b><?=esc($r['full_name'])?> · <?=esc($r['homestay'])?></b><p><?=nl2br(esc($r['comment']))?></p><small><?=esc(date('j M Y',strtotime($r['created_at'])))?></small><?php if($r['staff_reply']):?><blockquote>StayEase reply: <?=nl2br(esc($r['staff_reply']))?></blockquote><?php endif;?></article><?php endforeach;?><?php if(!$publicReviews):?><p>No public reviews yet.</p><?php endif;?></section>

<?php elseif(in_array($page,['reviews-customer','review-form'],true)): ?>
<?php $q=$pdo?$pdo->prepare("SELECT b.booking_id,h.name homestay,b.check_in,b.check_out,r.review_id,r.rating,r.comment FROM bookings b JOIN homestays h ON h.homestay_id=b.homestay_id LEFT JOIN reviews r ON r.booking_id=b.booking_id WHERE b.user_id=? AND b.status='Checked-out' ORDER BY b.check_out DESC"):null;$reviewRows=[];if($q){$q->execute([current_user()['user_id']]);$reviewRows=$q->fetchAll();}?>
<div class="screen-title"><div><span class="eyebrow">RATINGS & REVIEWS</span><h1>My reviews</h1><p>Share feedback for stays marked as checked out.</p></div></div><?php foreach($reviewRows as $r):?><form class="mock-panel customer-form" method="post"><input type="hidden" name="action" value="save_review"><input type="hidden" name="booking_id" value="<?=(int)$r['booking_id']?>"><h2><?=esc($r['homestay'])?> · <?=esc($r['check_in'])?></h2><label class="mock-field"><span>RATING</span><select name="rating"><?php for($star=5;$star>=1;$star--):?><option value="<?=$star?>" <?=$star===(int)($r['rating']??5)?'selected':''?>><?=$star?> star<?=$star===1?'':'s'?></option><?php endfor;?></select></label><label class="mock-field"><span>YOUR REVIEW</span><textarea name="comment" minlength="5" rows="4" required><?=esc($r['comment']??'')?></textarea></label><button class="mock-button primary">Save review</button></form><?php endforeach;?><?php if(!$reviewRows):?><div class="empty-state"><h2>No completed stays ready for review</h2></div><?php endif;?>

<?php elseif($page==='reviews-admin'): ?>
<?php $reviews=$pdo?$pdo->query('SELECT r.*,b.booking_id,u.full_name customer,h.name homestay FROM reviews r JOIN bookings b ON b.booking_id=r.booking_id JOIN users u ON u.user_id=b.user_id JOIN homestays h ON h.homestay_id=b.homestay_id ORDER BY r.created_at DESC')->fetchAll():[];?><div class="screen-title"><div><span class="eyebrow">RATINGS & REVIEWS</span><h1>Review moderation</h1><p>Reply to customer feedback and hide inappropriate reviews.</p></div></div><?php foreach($reviews as $r):?><section class="mock-panel"><div class="review-item"><div class="review-stars"><?=str_repeat('★',(int)$r['rating'])?></div><b><?=esc($r['customer'])?> · <?=esc($r['homestay'])?> · <?=esc($r['status'])?></b><p><?=nl2br(esc($r['comment']))?></p><form class="customer-form" method="post"><input type="hidden" name="review_id" value="<?=(int)$r['review_id']?>"><label class="mock-field"><span>STAFF REPLY</span><textarea name="staff_reply" rows="2"><?=esc($r['staff_reply'])?></textarea></label><button class="text-link" name="action" value="reply_review">Save reply</button><button class="text-link" name="action" value="moderate_review"><input type="hidden" name="status" value="<?=$r['status']==='Visible'?'Hidden':'Visible'?>"><?=$r['status']==='Visible'?'Hide':'Show'?> review</button></form></div></section><?php endforeach;?><?php if(!$reviews):?><div class="empty-state">No reviews have been submitted.</div><?php endif;?>
<?php endif; ?>
</main>
